-- WordMaster 统一数据库结构（MySQL 8 参考版）
CREATE DATABASE IF NOT EXISTS wordmaster DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE wordmaster;

CREATE TABLE user (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(50) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, nickname VARCHAR(50), email VARCHAR(100), role VARCHAR(20) NOT NULL DEFAULT 'student', status TINYINT NOT NULL DEFAULT 1, create_time DATETIME DEFAULT CURRENT_TIMESTAMP, update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE word (id BIGINT PRIMARY KEY AUTO_INCREMENT, word VARCHAR(100) NOT NULL UNIQUE, meaning VARCHAR(500) NOT NULL, phonetic VARCHAR(100), level VARCHAR(20), create_time DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE exam (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(120) NOT NULL, description VARCHAR(500), creator_id BIGINT NOT NULL, start_time DATETIME NOT NULL, end_time DATETIME NOT NULL, duration_minutes INT NOT NULL DEFAULT 30, status VARCHAR(20) NOT NULL DEFAULT 'published', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (creator_id) REFERENCES user(id));
CREATE TABLE exam_question (id BIGINT PRIMARY KEY AUTO_INCREMENT, exam_id BIGINT NOT NULL, word_id BIGINT NOT NULL, question_type VARCHAR(30) NOT NULL DEFAULT 'en_to_cn', base_order INT NOT NULL, UNIQUE KEY uq_exam_word (exam_id, word_id), FOREIGN KEY (exam_id) REFERENCES exam(id) ON DELETE CASCADE, FOREIGN KEY (word_id) REFERENCES word(id));
CREATE TABLE exam_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, exam_id BIGINT NOT NULL, user_id BIGINT NOT NULL, total_questions INT NOT NULL, correct_count INT DEFAULT 0, score DECIMAL(5,2) DEFAULT 0, status VARCHAR(20) DEFAULT 'in_progress', start_time DATETIME DEFAULT CURRENT_TIMESTAMP, end_time DATETIME, UNIQUE KEY uq_exam_attempt (exam_id, user_id), FOREIGN KEY (exam_id) REFERENCES exam(id), FOREIGN KEY (user_id) REFERENCES user(id));
CREATE TABLE answer_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, attempt_id BIGINT NOT NULL, exam_question_id BIGINT NOT NULL, word_id BIGINT NOT NULL, user_answer VARCHAR(500), correct_answer VARCHAR(500) NOT NULL, question_type VARCHAR(30) NOT NULL, is_correct TINYINT NOT NULL DEFAULT 0, question_order INT NOT NULL, FOREIGN KEY (attempt_id) REFERENCES exam_record(id) ON DELETE CASCADE, FOREIGN KEY (exam_question_id) REFERENCES exam_question(id), FOREIGN KEY (word_id) REFERENCES word(id));
